// Reading plans. Definitions are JSON files in the repo (generated by
// scripts/build-plans.mjs); a user can also build a "custom" plan, whose days
// are stored on the user_plans row itself.
import john21 from "../features/plans/data/john-21.json";
import nt90 from "../features/plans/data/nt-90.json";
import bible365 from "../features/plans/data/bible-365.json";
import { chapterKey } from "./books.js";
import { isoDate, addDays } from "./format.js";

export const PLANS = [john21, nt90, bible365];
const BY_KEY = Object.fromEntries(PLANS.map((p) => [p.key, p]));

/** Days of a user's plan as [[{ book, chapter }, …], …]. */
export function planDays(userPlan) {
  if (!userPlan) return [];
  if (userPlan.plan_key === "custom") return Array.isArray(userPlan.custom_readings) ? userPlan.custom_readings : [];
  return (BY_KEY[userPlan.plan_key]?.days || []).map((day) => day.map(([book, chapter]) => ({ book, chapter })));
}

export function planName(userPlan) {
  if (!userPlan) return "";
  if (userPlan.plan_key === "custom") return "Every chapter I have not read";
  return BY_KEY[userPlan.plan_key]?.name || "Reading plan";
}

/** "John 3", "Genesis 1–3", "Malachi 4; Matthew 1–2". */
export function readingLabel(day) {
  const parts = [];
  for (const { book, chapter } of day || []) {
    const last = parts[parts.length - 1];
    if (last && last.book === book && last.to === chapter - 1) last.to = chapter;
    else parts.push({ book, from: chapter, to: chapter });
  }
  return parts.map((p) => `${p.book} ${p.from}${p.to !== p.from ? `–${p.to}` : ""}`).join("; ");
}

/** The plan the user is following now (the newest active row), or null. */
export function activePlan(userPlans) {
  return [...userPlans].filter((p) => p.active).sort((a, b) => String(b.started_on).localeCompare(String(a.started_on)))[0] || null;
}

/**
 * Where a plan stands, derived from reading_progress (nothing is stored).
 *
 * A plan day is complete when every chapter in it was marked read on or after
 * the day the plan started. The plan "advances" as days are completed: the
 * current day is the first incomplete one.
 */
export function planState(userPlan, progressRows, today = isoDate()) {
  const days = planDays(userPlan);
  const total = days.length;
  if (!total) return null;
  const started = String(userPlan.started_on || today).slice(0, 10);
  const readOn = new Map();
  for (const r of progressRows) {
    const date = isoDate(r.read_at);
    if (date >= started) readOn.set(chapterKey(r.book, r.chapter), date);
  }
  const completedOn = days.map((day) => {
    let latest = "";
    for (const c of day) {
      const d = readOn.get(chapterKey(c.book, c.chapter));
      if (!d) return null;
      if (d > latest) latest = d;
    }
    return latest;
  });
  let current = completedOn.findIndex((d) => !d);
  const finished = current === -1;
  if (finished) current = total;
  const doneToday = current > 0 && completedOn[current - 1] === today;
  const index = finished ? total - 1 : doneToday ? current - 1 : current;
  const completedDates = new Set(completedOn.filter(Boolean));
  return {
    days, total, finished, doneToday,
    index,                          // zero-based day to show as "today"
    dayNumber: index + 1,
    reading: days[index],
    nextReading: finished ? null : days[current],
    doneCount: completedOn.filter(Boolean).length,
    percent: Math.round(((finished ? total : index + 1) / total) * 100),
    started, completedDates,
    remainingToday: finished || doneToday ? [] : days[current].filter((c) => !readOn.has(chapterKey(c.book, c.chapter))),
  };
}

/** Monday-to-Sunday strip for the week containing `today`. */
export function weekStrip(state, today = isoDate()) {
  const [y, m, d] = today.split("-").map(Number);
  const weekday = (new Date(y, m - 1, d).getDay() + 6) % 7; // Monday = 0
  const monday = addDays(today, -weekday);
  return ["M", "T", "W", "T", "F", "S", "S"].map((letter, i) => {
    const date = addDays(monday, i);
    return {
      letter, date,
      name: new Date(...date.split("-").map((n, j) => (j === 1 ? n - 1 : Number(n)))).toLocaleDateString(undefined, { weekday: "long" }),
      isToday: date === today,
      done: !!state && state.completedDates.has(date),
      off: !!state && date < state.started,
    };
  });
}

/** Chunk unread chapters into days of `pace` chapters for a custom plan. */
export function buildCustomReadings(chapters, pace) {
  const days = [];
  for (let i = 0; i < chapters.length; i += pace) days.push(chapters.slice(i, i + pace).map(({ book, chapter }) => ({ book, chapter })));
  return days;
}
